  "Välj din avatar eller skapa en ny.": "Vælg din avatar, eller lav en ny.",
  "Välj en bok. Att läsa ut den tar en timme och ger en utbildningspoäng första gången.": "Vælg en bog. Det tager en time at læse den færdig, og første gang giver det et uddannelsespoint.",
  "Välj en fröpåse. Vattna bädden varje dag – två dagar utan vatten och plantorna vissnar. Skörden hamnar i skafferiet.": "Vælg en frøpose. Vand bedet hver dag – to dage uden vand, og planterne visner. Høsten ryger i spisekammeret.",
  "Välj en häst.": "Vælg en hest.",
  "Välj en låt – den går hemma tills du stänger av eller lägger dig. Alla låtar i Pixelstaden finns här.": "Vælg en sang – den spiller hjemme, indtil du slukker eller går i seng. Alle sange i Pixelkøbing er her.",
  "Välj en möbel först": "Vælg et møbel først",
  "Välj en ny frisyr eller färg först.": "Vælg en ny frisure eller farve først.",
  "Välj en ny frisyr eller hårfärg – förhandsbilden visar hur det blir på dig.": "Vælg en ny frisure eller hårfarve – billedet viser, hvordan det ser ud på dig.",
  "Välj ett belopp.": "Vælg et beløb.",
  "Välj ett märke": "Vælg et mærke",
  "Välj ett ställe på kartan.": "Vælg et sted på kortet.",
  "Välj färg – en ballong kostar {0}. Den följer med dig på tivolit hela dagen!": "Vælg farve – en ballon koster {0}. Den følger med dig i tivoliet hele dagen!",
  "Välj hur högt du siktar i varje mål. Du har klarat livet i Pixelstaden när alla fyra är nådda samtidigt.": "Vælg, hvor højt du sigter i hvert mål. Du har klaret livet i Pixelkøbing, når alle fire er nået samtidig.",
  "Välj hur mycket du vill sätta in.": "Vælg, hvor meget du vil sætte ind.",
  "Välj hur mycket du vill ta ut.": "Vælg, hvor meget du vil hæve.",
  "Välj kana. Trapporna upp är branta – håll i räcket.": "Vælg rutsjebane. Trapperne op er stejle – hold fast i gelænderet.",
  "Välj någon i laget – eller skriv ett eget förnamn och nummer.": "Vælg en fra holdet – eller skriv dit eget fornavn og nummer.",
  "Välj något från menyn först!": "Vælg noget fra menuen først!",
  "Välj något i butiken så slår jag in det!": "Vælg noget i butikken, så slår jeg det ind!",
  "Välkommen fram!": "Velkommen hertil!",
  "Välkommen in! Värm upp lite först så går lyften lättare.": "Velkommen indenfor! Varm lidt op først, så går løftene lettere.",
  "Välkommen in! ✨": "Velkommen indenfor! ✨",
  "Välkommen ombord! Vad får det lov att vara?": "Velkommen om bord! Hvad skulle det være?",
  "Välkommen till BLIXT!": "Velkommen til LYN!",
  "Välkommen till Biblioteket! Ta en bok från hyllan och sätt dig vid ett bord. Varje utläst bok ger en utbildningspoäng.": "Velkommen til Biblioteket! Tag en bog fra hylden og sæt dig ved et bord. Hver færdiglæst bog giver et uddannelsespoint.",
  "Välkommen till Bio Pixel!": "Velkommen til Pixel Bio!",
  "Välkommen till Gamla stan! Huset bakom mig är från 1699 – titta på årtalet i gaveln.": "Velkommen til Den Gamle By! Huset bag mig er fra 1699 – se årstallet på gavlen.",
  "Välkommen till Klipp & Klo! Har du ett husdjur så gör vi det jättefint här. ✂️": "Velkommen til Klip & Klo! Har du et kæledyr, gør vi det rigtig fint her. ✂️",
  "Välkommen till Klipp & Klo! ✂️ Klicka på trimbordet så fixar vi ditt djur.": "Velkommen til Klip & Klo! ✂️ Klik på trimmebordet, så gør vi dit dyr fint.",
  "Välkommen till Kurr! ☕ Fika vid disken – och klappa gärna katterna, de älskar det.": "Velkommen til Mjav! ☕ Køb kaffe og kage ved disken – og klap gerne kattene, de elsker det.",
  "Välkommen till Museet! Titta på föremålen – skyltarna berättar. När du sett tre stycken får du ta quizet hos mig.": "Velkommen til Museet! Kig på genstandene – skiltene fortæller. Når du har set tre, må du tage quizzen hos mig.",
  "Välkommen till Pixel Gym! Hantlarna och boxsäcken ger STYRKA, gruppasset KONDITION och dansgolvet RYTM.": "Velkommen til Pixel Gym! Håndvægtene og boksesækken giver STYRKE, holdtræningen KONDI og dansegulvet RYTME.",
  "Välkommen till Pixelbanken!": "Velkommen til Pixelbanken!",
  "Välkommen till frisören! Sätt dig i en ledig stol, så fixar vi håret. 💇": "Velkommen til frisøren! Sæt dig i en fri stol, så ordner vi håret. 💇",
  "Välkommen till kassan.": "Velkommen til kassen.",
  "Välkommen till utställningen! Anmäl ditt djur här vid disken – det kostar 100 kr.": "Velkommen til udstillingen! Tilmeld dit dyr her ved disken – det koster 100 kr.",
